/**
 * Opt-in PR progress surfaces: Checks API run + sticky banner comment.
 */
import { createGitHubCheckRun, createGitHubIssueComment, GitHubApiError, updateGitHubCheckRun, updateGitHubIssueComment, } from "./api.js";
import { formatGitHubOutboundComment } from "./binding.js";
/** Merge-box check titles stay short; GitHub allows 1024, we clip to 140. */
const STATUS_DESCRIPTION_MAX = 140;
export function resolveCommitStatusProgress(progress) {
    if (progress?.commitStatus === undefined || progress.commitStatus === false) {
        return null;
    }
    return progress.commitStatus;
}
export function resolveBannerProgress(progress) {
    if (progress?.banner === undefined || progress.banner === false) {
        return null;
    }
    return progress.banner;
}
export function progressPhaseCopy(input) {
    const custom = input.copy?.[input.phase];
    if (custom !== undefined && custom.trim() !== "") {
        return custom;
    }
    switch (input.phase) {
        case "pending":
            return `${input.label} running`;
        case "success":
            return `${input.label} finished`;
        case "failure":
            return `${input.label} failed`;
        default: {
            const unexpected = input.phase;
            return unexpected;
        }
    }
}
function clipStatusDescription(text) {
    if (text.length <= STATUS_DESCRIPTION_MAX) {
        return text;
    }
    return `${text.slice(0, STATUS_DESCRIPTION_MAX - 1)}…`;
}
function progressLabel(options, context) {
    const bot = options.botName?.trim();
    if (bot !== undefined && bot !== "") {
        return bot;
    }
    if (context !== undefined && context.trim() !== "") {
        return context;
    }
    return "Agent";
}
/**
 * Post or update opt-in progress surfaces for a turn phase.
 * Soft-fails on API errors (same posture as eyes / reply delivery).
 */
export async function applyGitHubProgress(input) {
    const configured = resolveCommitStatusProgress(input.options.progress);
    const banner = resolveBannerProgress(input.options.progress);
    if (configured === null && banner === null) {
        return;
    }
    const override = input.channel.state.progressCheckName?.trim();
    const commitStatus = configured === null || override === undefined || override === ""
        ? configured
        : { ...configured, context: override };
    const tasks = [];
    if (commitStatus !== null) {
        tasks.push(postProgressCheckRun({
            phase: input.phase,
            sessionId: input.sessionId,
            channel: input.channel,
            options: input.options,
            commitStatus,
        }));
    }
    if (banner !== null) {
        tasks.push(upsertBanner({
            phase: input.phase,
            channel: input.channel,
            options: input.options,
            banner,
            context: commitStatus?.context,
        }));
    }
    await Promise.all(tasks);
}
function resolveProgressDetailsUrl(input) {
    if (input.sessionId === undefined || input.commitStatus.detailsUrl === undefined) {
        return undefined;
    }
    const url = input.commitStatus.detailsUrl(input.sessionId)?.trim();
    return url === "" ? undefined : url;
}
function appendSummaryLink(summary, detailsUrl, linkText) {
    const label = linkText?.trim();
    if (detailsUrl === undefined || label === undefined || label === "") {
        return summary;
    }
    return `${summary}\n\n[${label}](${detailsUrl})`;
}
async function postProgressCheckRun(input) {
    const state = input.channel.state;
    if (state.owner === "" || state.repo === "" || state.headSha === null || state.headSha === "") {
        return;
    }
    const sha = state.headSha;
    const phaseCopy = progressPhaseCopy({
        copy: input.commitStatus,
        phase: input.phase,
        label: progressLabel(input.options, input.commitStatus.context),
    });
    const title = clipStatusDescription(input.commitStatus.outputTitle === "context" ? input.commitStatus.context : phaseCopy);
    const detailsUrl = resolveProgressDetailsUrl({
        sessionId: input.sessionId,
        commitStatus: input.commitStatus,
    });
    const write = {
        name: input.commitStatus.context,
        ...checkRunPhaseFields(input.phase, input.commitStatus.failureConclusion),
        ...(detailsUrl === undefined ? {} : { detailsUrl }),
        output: {
            title,
            summary: appendSummaryLink(phaseCopy, detailsUrl, input.commitStatus.summaryLinkText),
        },
    };
    const resource = {
        api: input.options.api,
        credentials: input.options.credentials,
        installationId: state.installationId ?? undefined,
        owner: state.owner,
        repo: state.repo,
    };
    const reuseId = state.progressCheckRunId !== null && state.progressCheckRunSha === sha
        ? state.progressCheckRunId
        : null;
    // Completed runs cannot go back to in_progress. GitHub often 200s and
    // leaves the run completed (sometimes 422). Create a new run so a later
    // turn on the same SHA shows pending again.
    const completedBlocksReuse = write.status === "in_progress" && state.progressCheckRunCompleted === true;
    try {
        if (reuseId !== null && !completedBlocksReuse) {
            try {
                await updateGitHubCheckRun({
                    ...resource,
                    ...write,
                    checkRunId: reuseId,
                });
                state.progressCheckRunCompleted = write.status === "completed";
                return;
            }
            catch (error) {
                if (!shouldRecreateCheckRun(error, write.status)) {
                    return;
                }
                state.progressCheckRunId = null;
                state.progressCheckRunSha = null;
                state.progressCheckRunCompleted = false;
            }
        }
        const created = await createGitHubCheckRun({
            ...resource,
            ...write,
            sha,
        });
        state.progressCheckRunId = created.id;
        state.progressCheckRunSha = sha;
        state.progressCheckRunCompleted = write.status === "completed";
    }
    catch {
        // Soft-fail: missing token / permission is fine.
    }
}
function shouldRecreateCheckRun(error, status) {
    if (!(error instanceof GitHubApiError)) {
        return false;
    }
    if (error.status === 404) {
        return true;
    }
    return error.status === 422 && status === "in_progress";
}
function checkRunPhaseFields(phase, failureConclusion = "failure") {
    if (phase === "pending") {
        return { status: "in_progress" };
    }
    return {
        status: "completed",
        conclusion: phase === "success" ? "success" : failureConclusion,
    };
}
async function upsertBanner(input) {
    const state = input.channel.state;
    const issueNumber = state.issueNumber ?? state.pullRequestNumber;
    if (state.owner === "" || state.repo === "" || issueNumber === null) {
        return;
    }
    const body = formatGitHubOutboundComment(progressPhaseCopy({
        copy: input.banner,
        phase: input.phase,
        label: progressLabel(input.options, input.context),
    }));
    const resource = {
        api: input.options.api,
        credentials: input.options.credentials,
        installationId: state.installationId ?? undefined,
        owner: state.owner,
        repo: state.repo,
    };
    try {
        if (state.progressBannerCommentId !== null) {
            try {
                await updateGitHubIssueComment({
                    ...resource,
                    body,
                    commentId: state.progressBannerCommentId,
                });
                return;
            }
            catch (error) {
                if (!(error instanceof GitHubApiError) || error.status !== 404) {
                    return;
                }
                // Comment gone; clear sticky id and recreate below.
                state.progressBannerCommentId = null;
            }
        }
        const posted = await createGitHubIssueComment({
            ...resource,
            body,
            issueNumber,
        });
        state.progressBannerCommentId = posted.id;
    }
    catch {
        // Soft-fail.
    }
}
